/**
 * Rewrites stored `api.dicebear.com` avatar URLs to this server's own endpoint.
 *
 * Default avatars were generated by a third party and the *URL* was saved on
 * the user, so switching the code to draw them locally is not enough on its
 * own — every row written before the switch still points at dicebear, and
 * still costs a request to them from every browser that renders it.
 *
 * The seed is carried across unchanged, so each account keeps the face it has
 * had all along; only the host serving it changes.
 *
 * Reports what it would do and writes nothing unless you pass --apply.
 * Re-running it after that finds nothing, so it is safe to run twice.
 *
 *   npx tsx scripts/migrate-avatar-urls.ts
 *   npx tsx scripts/migrate-avatar-urls.ts --apply
 */
import "dotenv/config";
import mongoose from "mongoose";
import { User } from "../server/models";
import { avatarUrlForSeed } from "../server/services/avatar";

const DICEBEAR_PREFIX = "https://api.dicebear.com/";

/** The seed dicebear was asked for, or the account's own fallback seed. */
function seedFrom(avatar: string, username?: string, firebaseUid?: string): string {
  const seed = new URL(avatar).searchParams.get("seed");
  // A stored URL with no seed drew dicebear's own default face. There is
  // nothing to preserve, so fall back to what a new account would get.
  return seed || username || firebaseUid || "user";
}

async function main() {
  const apply = process.argv.includes("--apply");
  const uri = process.env.MONGODB_URI;
  if (!uri) throw new Error("MONGODB_URI is not set");

  await mongoose.connect(uri, { serverSelectionTimeoutMS: 10000 });

  const stale = await User.find({ avatar: new RegExp(`^${DICEBEAR_PREFIX}`) })
    .select("_id username firebaseUid avatar")
    .lean();

  console.log(`${stale.length} user(s) with a dicebear avatar URL stored.\n`);

  for (const user of stale) {
    const next = avatarUrlForSeed(seedFrom(user.avatar!, user.username, user.firebaseUid));
    console.log(`  ${user.username || user._id}\n    ${user.avatar}\n -> ${next}`);
    if (apply) {
      await User.updateOne({ _id: user._id }, { $set: { avatar: next } });
    }
  }

  const left = await User.countDocuments({ avatar: new RegExp(`^${DICEBEAR_PREFIX}`) });
  console.log(
    apply
      ? `\nRewrote ${stale.length}. ${left} still pointing at dicebear.`
      : `\nDry run — nothing written. Pass --apply to rewrite these ${stale.length}.`
  );

  await mongoose.disconnect();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
